"""
core/config.py — All tunable constants in one place.
Comment each threshold with how it was derived (p95 of real data, or starter default).
"""

from __future__ import annotations

import os

from dotenv import load_dotenv

load_dotenv()

# ── Dataset / data source ─────────────────────────────────────────────────────
# icij: ICIJ Offshore Leaks subset (ODbL / CC BY-SA)
# synthetic: generated by data/make_synthetic.py (fictitious names, for tests/demo)
DATA_SOURCE: str = os.getenv("DATA_SOURCE", "icij")

# ── FalkorDB connection ──────────────────────────────────────────────────────
FALKORDB_HOST: str = os.getenv("FALKORDB_HOST", "localhost")
FALKORDB_PORT: int = int(os.getenv("FALKORDB_PORT", "6379"))
FALKORDB_USERNAME: str = os.getenv("FALKORDB_USERNAME", "")
FALKORDB_PASSWORD: str = os.getenv("FALKORDB_PASSWORD", "")
FALKORDB_SSL: bool = os.getenv("FALKORDB_SSL", "false").lower() == "true"
GRAPH_NAME: str = os.getenv("GRAPH_NAME", "ownership")

# ── NVIDIA LLM ───────────────────────────────────────────────────────────────
NVIDIA_API_KEY: str = os.getenv("NVIDIA_API_KEY", "")
NVIDIA_BASE_URL: str = "https://integrate.api.nvidia.com/v1"
# nvidia/nemotron-3-super-120b-a12b: benchmarked and verified text model
# (passed 7/10 tool calling prompts per bench_models.py).
# Replaces vision model meta/llama-3.2-11b-vision-instruct.
NVIDIA_MODEL: str = os.getenv("NVIDIA_MODEL", "nvidia/nemotron-3-super-120b-a12b")

# ── LLM budget ───────────────────────────────────────────────────────────────
MAX_LLM_CALLS_PER_RUN: int = 8  # hard cap per investigation
LLM_RETRY_MAX: int = 3  # retries on 429/5xx
LLM_RETRY_BASE_DELAY: float = 2.0  # seconds; doubles each retry
DAILY_LLM_CAP: int = int(os.getenv("DAILY_LLM_CAP", "300"))
NO_LLM: bool = os.getenv("NO_LLM", "0") == "1"

# ── FastAPI ───────────────────────────────────────────────────────────────────
ALLOWED_ORIGINS: list[str] = [
    o.strip() for o in os.getenv("ALLOWED_ORIGINS", "http://localhost:8000").split(",") if o.strip()
]
RATE_LIMIT_INVESTIGATIONS_PER_HOUR: int = int(os.getenv("RATE_LIMIT_INVESTIGATIONS_PER_HOUR", "60"))
CONCURRENT_INVESTIGATIONS: int = 4

# ── Graph query limits ────────────────────────────────────────────────────────
QUERY_TIMEOUT_MS: int = 10_000  # per query
MAX_DEPTH: int = int(os.getenv("MAX_DEPTH", "4"))  # max traversal depth; 4 supports 3-hop demo contrast
OWNERSHIP_CHAIN_ROW_CAP: int = 200
SHARED_LINKS_LIMIT: int = 10
RESOLVE_LIMIT: int = 5
CLUSTER_NODE_CAP: int = 500
RECALL_CASES_LIMIT: int = 5

# ── Relationship type allowlist ───────────────────────────────────────────────
# Normalised to UPPER_SNAKE; must match Cypher relationship types loaded into FalkorDB.
ALLOWED_REL_TYPES: frozenset[str] = frozenset(
    {
        "OFFICER_OF",
        "REGISTERED_ADDRESS",
        "INTERMEDIARY_OF",
        "SAME_NAME_AS",
        "SAME_ADDRESS_AS",
        "CONNECTED_TO",
        "RELATED_ENTITY",
        "UNDERLYING",
        "SHAREHOLDER_OF",
        "DIRECTOR_OF",
        "BENEFICIARY_OF",
        "ADDRESS_OF",
        "SAME_AS",
        "SAME_COMPANY_AS",
        "SIMILAR",
    }
)

# ── Edge weights (lower = stronger evidence link) ─────────────────────────────
# Used by SPpaths weightProp:'weight' and the WATCHLIST_PATH rule.
EDGE_WEIGHT: dict[str, float] = {
    "OFFICER_OF": 1.0,
    "SHAREHOLDER_OF": 1.0,
    "BENEFICIARY_OF": 1.0,
    "DIRECTOR_OF": 1.0,
    "UNDERLYING": 1.5,
    "INTERMEDIARY_OF": 2.0,
    "CONNECTED_TO": 2.5,
    "RELATED_ENTITY": 2.5,
    "REGISTERED_ADDRESS": 3.0,
    "ADDRESS_OF": 3.0,
    "SAME_NAME_AS": 4.0,
    "SAME_ADDRESS_AS": 4.0,
    "SAME_AS": 4.0,
    "SAME_COMPANY_AS": 4.0,
    "SIMILAR": 4.0,
}
DEFAULT_EDGE_WEIGHT: float = 2.5
LOAD_BATCH_SIZE: int = int(os.getenv("LOAD_BATCH_SIZE", "1000"))

# ── Rule thresholds (Calibrated on active ICIJ SAM/SEY dataset) ────────────────
# Address degree distribution: min=1, p50=1.0, p90=2.0, p95=5.0, max=11.
ADDRESS_HUB_MIN: int = 5  # Exactly p95 of Address degree distribution

# Officer degree distribution: min=1, p50=1.0, p90=1.0, p95=1.0, p99=3.0, max=3882.
# 95%+ of officers belong to 1 company; >=3 links isolates high-volume nominee directors (p99).
OFFICER_HUB_MIN: int = 3  # Exactly p99 of Officer degree distribution

# Intermediary degree distribution: min=1, p50=2.0, p90=14.1, p95=32.0, max=3993.
INTERMEDIARY_MIN: int = 15  # Calibrated to ~p90 of Intermediary degree distribution

PATH_COST_MAX: float = 8.0  # Max weighted path cost for WATCHLIST_PATH rule

# Zero/low-link entities (degree 0 or 1) have insufficient connections to clear; must return insufficient_evidence.
MIN_LINKS: int = 2  # At least 2 verified links required for a conclusive verdict

# Scratch graph centrality threshold: betweenness >= 0.05 indicates bridge hub (~p90 in scratch clusters)
CENTRALITY_BETWEENNESS_MIN: float = 0.05

# MCP tool routing switch (default: on)
USE_MCP: bool = os.getenv("USE_MCP", "1").lower() in ("1", "true", "yes")

# ── Verdict enum values (also used for Case node) ─────────────────────────────
VERDICTS: frozenset[str] = frozenset({"clear", "review", "escalate", "insufficient_evidence"})
